function buildObstacles(){clearSpray();for(const o of obstacles){if(o.obj.parent===world){world.remove(o.obj);o.obj.traverse(m=>{m.geometry?.dispose();if(m.material)m.material.dispose();});}}obstacles=[];for(const spec of initialHazards(track.length))addObstacle(spec);}
