 const pitch=Math.atan(grade)+clamp(-v.acceleration*.0015,-.032,.045),roll=clamp(-v.lateralAccel*.0028,-.075,.075);
 d.bodyPitch=(d.bodyPitch||0)+(pitch-(d.bodyPitch||0))*(1-Math.exp(-dt*12));d.bodyRoll=(d.bodyRoll||0)+(roll-(d.bodyRoll||0))*(1-Math.exp(-dt*9));
