function addRacerLabel(obj,name,index){const c=document.createElement('canvas');c.width=512;c.height=96;const ctx=c.getContext('2d');ctx.fillStyle='rgba(12,31,25,.84)';ctx.fillRect(0,0,512,96);ctx.fillStyle=['#eecb82','#a5dce1','#c9db9c'][index];ctx.fillRect(0,0,9,96);ctx.font='600 38px sans-serif';ctx.textAlign='center';ctx.fillStyle='#eff4df';ctx.fillText(name,262,62);const label=new THREE.Sprite(new THREE.SpriteMaterial({map:new THREE.CanvasTexture(c),transparent:true,depthTest:true}));label.position.set(0,2.15,0);label.scale.set(2.2,.42,1);obj.add(label);}
function updateOpponents(dt,oldPlayerS){
 const traffic=[...opponents,{s:progress,off:lateral,speed:velocity}];
 for(const o of opponents){const oldS=o.s;updateRacer(o,dt,{track:trackIndex,length:track.length,grip:track.grip,cars,obstacles,traffic,time:elapsed});
  const gap=o.s-progress,oldGap=oldS-oldPlayerS,crossed=gap*oldGap<=0;
  if(playerFinishTime===null&&(Math.abs(gap)<1.8||crossed)&&Math.abs(o.off-lateral)<1.25&&o.finishTime===null){const side=lateral>=o.off?1:-1,overlap=(1.25-Math.abs(o.off-lateral))*.5;vehicle.x+=side*overlap*.55;o.v.x-=side*overlap*.55;vehicle.lateral=vehicle.x-roadCenter(vehicle.s,trackIndex);o.v.lateral=o.v.x-roadCenter(o.v.s,trackIndex);const average=(vehicle.speed+o.v.speed)*.5;vehicle.speed=vehicle.speed*.85+average*.15;o.v.speed=o.v.speed*.85+average*.15;lateral=vehicle.lateral;velocity=vehicle.speed;o.off=o.v.lateral;o.speed=o.v.speed;}
  updateVehicleVisual(o.obj,o.v,dt);
 }
 // Rival-to-rival contact uses the same lane separation and costs speed.
 for(let i=0;i<opponents.length;i++)for(let j=i+1;j<opponents.length;j++){const a=opponents[i],b=opponents[j];if(Math.abs(a.s-b.s)<1.7&&Math.abs(a.off-b.off)<1.1&&a.finishTime===null&&b.finishTime===null){const direction=a.off>=b.off?1:-1;a.v.x+=direction*dt*.7;b.v.x-=direction*dt*.7;a.v.speed*=.995;b.v.speed*=.995;}}
}
function updateStandings(){$('position').innerHTML=currentRank()+' <span>/ 4</span>';const entrants=opponents.map(o=>({name:o.profile.name,s:o.s,time:o.finishTime,tag:o.control?.brake?'FREN':o.passSide?'SOLLAMA':''}));entrants.push({name:playerName(),s:progress,time:playerFinishTime,player:true});entrants.sort((a,b)=>a.time!==null&&b.time!==null?a.time-b.time:a.time!==null?-1:b.time!==null?1:b.s-a.s);$('standings').innerHTML=entrants.map((e,i)=>`<div class="${e.player?'is-player':''}"><b>${i+1}</b><span>${escapeText(e.name)}</span><small>${e.player?'SEN':e.time!==null?'FİNİŞ':e.tag||((e.s>=progress?'+':'−')+Math.round(Math.abs(e.s-progress))+' m')}</small></div>`).join('');}
function updateSun(){if(!sunLight||!cart)return;const p=cart.position;sunLight.position.set(p.x-48,p.y+90,p.z+35);sunLight.target.position.set(p.x,p.y,p.z-8);sunLight.target.updateMatrixWorld();}

function textPanel(text,plate=false){const c=document.createElement('canvas');c.width=768;c.height=plate?192:160;const ctx=c.getContext('2d');ctx.fillStyle=plate?'#eeeeda':'#17382c';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle=plate?'#22362e':'#c8d79c';ctx.lineWidth=10;ctx.strokeRect(6,6,c.width-12,c.height-12);if(plate){ctx.fillStyle='#285085';ctx.fillRect(13,13,60,c.height-26);ctx.fillStyle='white';ctx.font='bold 34px sans-serif';ctx.textAlign='center';ctx.fillText('TR',43,c.height-35);}ctx.fillStyle=plate?'#16271e':'#e9edcc';ctx.font=(plate?'bold 90px':'600 70px')+' sans-serif';ctx.textAlign='center';ctx.fillText(text,plate?416:384,plate?130:108,plate?650:710);const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;return new THREE.MeshStandardMaterial({map:texture,roughness:.6});}
function applyLivery(obj,custom,name){for(const mesh of obj.userData.livery||[]){obj.remove(mesh);mesh.geometry.dispose();mesh.material.map?.dispose();mesh.material.dispose();}obj.userData.livery=[];const add=(text,plate,w,h,x,y,z,rot=0)=>{const p=new THREE.Mesh(new THREE.PlaneGeometry(w,h),textPanel(text,plate));p.position.set(x,y,z);p.rotation.y=rot;obj.add(p);obj.userData.livery.push(p);};add(cleanPlate(custom?.plate),true,.68,.17,0,.63,1.09);const label=cleanName(custom?.nickname,'')||name;add(label,false,.65,.135,0,1.03,.786);add(label,false,.8,.17,.57,.64,-.06,Math.PI/2);add(label,false,.8,.17,-.57,.64,-.06,-Math.PI/2);if(custom?.paint)obj.traverse(o=>{if(o.material?.userData?.paintable)o.material.color.set(custom.paint);});}
function fillCustomizationForm(){const c=cars[garageChoice],saved=customFor(garageSave,c.id),owned=garageSave.owned.includes(c.id);$('customForLabel').textContent=c.name+' için isim, plaka ve renk düzenle.';$('driverName').value=playerName();$('carNickname').value=saved.nickname;$('carPlate').value=saved.plate;$('carPaint').value=saved.paint||'#'+c.color.toString(16).padStart(6,'0');for(const id of ['driverName','carNickname','carPlate','carPaint','saveCustom'])$(id).disabled=!owned;$('customMessage').textContent=owned?'İsmin ve plakan aracın üzerinde görünür. Değişiklikler bu tarayıcıya kaydedilir.':'Özelleştirmek için önce aracı garajına ekle.';}
function formCustom(){return {driverName:$('driverName').value,nickname:$('carNickname').value,plate:$('carPlate').value,paint:$('carPaint').value};}
function previewCustomization(){if(garageModel&&garageSave.owned.includes(cars[garageChoice].id))applyLivery(garageModel,formCustom(),cleanName($('driverName').value));}
for(const id of ['driverName','carNickname','carPlate','carPaint'])$(id).addEventListener('input',previewCustomization);
$('customForm').addEventListener('submit',e=>{e.preventDefault();try{garageSave=saveCustomization(garageSave,cars[garageChoice].id,formCustom());persistGarage();if(garageChoice===carIndex)selectCar(carIndex);refreshGarage();$('customMessage').textContent='Kaydedildi! Yeni ismin, yazın ve plakan yola hazır.';if($('sfxEnabled').checked)drivingAudio.menu('buy');}catch(err){$('customMessage').textContent=err.message;}});
function updateResultTable(){if(playerFinishTime===null)return;const player={name:playerName(),car:cars[carIndex].name,s:track.length,time:playerFinishTime,player:true};const rows=resultRows(player,opponents.map(o=>({name:o.profile.name,car:cars[o.profile.car].name,s:o.s,time:o.finishTime})));$('resultsRows').innerHTML=rows.map(r=>`<tr class="${r.rank===1&&r.time!==null?'winner ':''}${r.player?'you':''}"><td>${r.rank===1&&r.time!==null?'★':r.rank}</td><td><b>${escapeText(r.name)}</b>${r.player?'<small>SEN</small>':''}</td><td>${escapeText(r.car)}</td><td>${secondsText(r.time)}</td><td>${r.gap===null?'—':r.gap===0?'LİDER':'+'+r.gap.toFixed(2).replace('.',',')}</td></tr>`).join('');const complete=rows.every(r=>r.time!==null);$('resultsStatus').textContent=complete?'TÜM YARIŞÇILAR FİNİŞTE':'RAKİPLERİN SÜRELERİ CANLI GÜNCELLENİYOR';}

function resetDriftFX(){driftDustTimer=0;if(skidState?.mesh.parent===world){skidState.count=0;skidState.index=0;skidState.last=null;skidState.mesh.geometry.setDrawRange(0,0);}else skidState=null;}
function updateDriftFX(dt){if(!vehicle.isDrifting){if(skidState)skidState.last=null;return;}if(!skidState||skidState.mesh.parent!==world){const positions=new Float32Array(320*6),geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));geometry.setDrawRange(0,0);const mesh=new THREE.LineSegments(geometry,new THREE.LineBasicMaterial({color:0x14201b,transparent:true,opacity:.3,depthWrite:false}));mesh.frustumCulled=false;world.add(mesh);skidState={mesh,positions,count:0,index:0,last:null};}const points=cart.userData.wheels.filter(w=>w.position.z>0).map(w=>{const p=w.getWorldPosition(new THREE.Vector3());p.y=roadHeight(-p.z,p.x-roadCenter(-p.z,trackIndex))+.018;return p;});if(skidState.last){for(let i=0;i<points.length;i++){const a=skidState.last[i],b=points[i],at=skidState.index*6;skidState.positions.set([a.x,a.y,a.z,b.x,b.y,b.z],at);skidState.index=(skidState.index+1)%320;skidState.count=Math.min(320,skidState.count+1);}skidState.mesh.geometry.setDrawRange(0,skidState.count*2);skidState.mesh.geometry.attributes.position.needsUpdate=true;}skidState.last=points;driftDustTimer-=dt;if(driftDustTimer<=0&&track.weather==='clear'){sprayAt('dust');driftDustTimer=.15;}}

function currentRank(){return 1+opponents.filter(o=>playerFinishTime!==null?(o.finishTime!==null&&o.finishTime<playerFinishTime):(o.s>progress||o.finishTime!==null)).length;}

$('customizeJump').onclick=()=>{$('customizer').scrollIntoView({behavior:'smooth',block:'nearest'});};

function onlineProfile(){return {name:cleanName($('onlineName').value||playerName()),carId:cars[carIndex].id,custom:customFor(garageSave,cars[carIndex].id)};}
function showRoomDialog(){if($('result').open)$('result').close();if(!$('onlineDialog').open)$('onlineDialog').showModal();}
function renderRoom(room){const own=room.players.find(p=>p.id===roomClient.session?.id),host=room.host===own?.id;$('onlineEntry').hidden=true;$('roomPanel').hidden=false;$('leaveRoom').hidden=false;$('roomCode').textContent=room.code;$('roomMap').textContent=tracks[room.track].name+' · '+room.players.length+' / 4 YARIŞÇI';$('inviteLink').value=roomClient.invite();const local=/^(localhost|127\.0\.0\.1|\[::1\])$/.test(new URL(roomClient.invite()).hostname);$('inviteHint').textContent=local?'Bu yerel bağlantı aynı bilgisayardaki tarayıcılarda çalışır. Başka bilgisayardaki arkadaşın için sunucunun internete yayımlanması gerekir.':'Bağlantıyı arkadaşına gönder; aynı odaya katılsın.';$('roomPlayers').innerHTML=room.players.map(p=>`<div class="room-player ${p.ready?'is-ready':''}"><span class="player-avatar">${escapeText(p.profile.name.slice(0,1).toLocaleUpperCase('tr-TR'))}</span><div><b>${escapeText(p.profile.name)} ${p.id===room.host?'<small>ODA SAHİBİ</small>':''}</b><span>${escapeText(cars[p.profile.car].name)}</span></div><em>${!p.connected?'BAĞLANTI BEKLENİYOR':p.ready?'HAZIR ✓':'BEKLİYOR'}</em></div>`).join('')+Array.from({length:4-room.players.length},()=>'<div class="empty-player">+ Arkadaşın bekleniyor</div>').join('');$('readyRoom').textContent=own?.ready?'HAZIR DEĞİLİM':'HAZIRIM ✓';$('readyRoom').disabled=room.phase!=='lobby';$('startRoom').hidden=!host;$('startRoom').textContent=room.phase==='finished'?'YENİ YARIŞ İÇİN ODAYI AÇ ↗':'YARIŞI BAŞLAT ↗';$('startRoom').disabled=room.phase==='finished'?false:!room.canStart;$('roomHint').textContent=room.phase==='finished'?(host?'Yeni yarış için odayı aç; herkes tekrar hazır olsun.':'Yeni yarış için oda sahibini bekle.'):room.canStart?(host?'Herkes hazır. Yarışı başlatabilirsin.':'Herkes hazır. Oda sahibinin başlatmasını bekliyoruz.'):room.players.length<2?'Arkadaşını davet et. Yarış için en az 2 kişi gerekiyor.':'Herkes Hazırım dediğinde oda sahibi yarışı başlatabilir.';}
async function openOnline(){if(roomClient.room){renderRoom(roomClient.room);showRoomDialog();return;}$('onlineEntry').hidden=false;$('roomPanel').hidden=true;$('leaveRoom').hidden=true;$('onlineName').value=playerName();$('onlineCar').textContent=cars[carIndex].name;$('onlineTrackLabel').textContent=tracks[trackIndex].name+' · Ana menüde seçtiğin parkur';$('onlineStatus').textContent='';showRoomDialog();try{const config=await fetch('/api/config').then(r=>{if(!r.ok)throw Error();return r.json();});if(!config.online)throw Error();roomClient.publicOrigin=config.publicOrigin;}catch{$('onlineStatus').textContent='Çevrimiçi sunucu bu adreste çalışmıyor. Oyunu oda sunucusu üzerinden açmalısın.';}}
function restoreSolo(){onlineActive=false;onlineRoom=null;onlineResultShown=false;onlineHazardsSeen.clear();$('onlineDialog').close();$('result').close();$('networkBadge').hidden=true;$('again').disabled=false;$('again').textContent='BİR DAHA YARIŞ ↗';carIndex=Math.max(0,cars.findIndex(c=>c.id===garageSave.selected));build();menu();}
function leaveOnline(){roomClient.leave();}
function discardVehicle(obj){const shadow=obj.userData.contactShadow;if(shadow){world.remove(shadow);shadow.geometry.dispose();shadow.material.dispose();}world.remove(obj);const geometries=new Set(),materials=new Set();obj.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)materials.add(o.material);});for(const g of geometries)g.dispose();for(const m of materials){if(m.map&&![woodTex,gravelTex,contactMap].includes(m.map))m.map.dispose();m.dispose();}}
function syncRoomHazards(room,reset=false){if(reset){for(const o of obstacles){world.remove(o.obj);o.obj.traverse(m=>{m.geometry?.dispose();m.material?.dispose();});}obstacles=[];onlineHazardsSeen.clear();}for(const spec of room.hazards||[])if(!onlineHazardsSeen.has(spec.id)){addObstacle(spec);onlineHazardsSeen.add(spec.id);}}
function beginOnlineRace(room){const own=room.players.find(p=>p.id===roomClient.session?.id);if(!own)return;onlineActive=false;onlineRoom=room;trackIndex=room.track;carIndex=own.profile.car;build();start();for(const o of opponents)discardVehicle(o.obj);opponents=room.players.filter(p=>p.id!==own.id).map((p,i)=>{const obj=makeCart(p.profile.car,true,false);applyLivery(obj,p.profile.custom,p.profile.name);addRacerLabel(obj,p.profile.name,i);resetVehicleVisual(obj);world.add(obj);return {id:p.id,obj,profile:p.profile,v:p.v||newVehicle(trackIndex),s:p.v?.s||0,off:p.v?.lateral||0,speed:0,finishTime:p.finishTime};});applyLivery(cart,own.profile.custom,own.profile.name);syncRoomHazards(room,true);onlineActive=true;onlineEventSeen=0;onlineResultShown=false;playerFinishTime=null;resetVehicleVisual(cart);$('onlineDialog').close();$('pause').hidden=true;$('networkBadge').hidden=false;cameraYaw=own.v?.heading||roadHeading(0,trackIndex);}
function updateOnlineRace(dt){const room=roomClient.room;if(!room)return;onlineRoom=room;const own=room.players.find(p=>p.id===roomClient.session?.id);if(!own)return;const controls={throttle:!!(keys.w||keys.arrowup),brake:!!(keys.s||keys.arrowdown),handbrake:!!keys[' '],steer:(keys.a||keys.arrowleft?-1:0)+(keys.d||keys.arrowright?1:0)};const local=roomClient.advance(dt,controls);if(local){vehicle=local;progress=vehicle.s;lateral=vehicle.lateral;velocity=vehicle.speed;updateVehicleVisual(cart,vehicle,dt);updateDriftFX(dt);}for(const o of opponents){const p=room.players.find(p=>p.id===o.id),v=roomClient.sample(o.id);if(p&&v){o.v=v;o.s=v.s;o.off=v.lateral;o.speed=v.speed;o.finishTime=p.finishTime;updateVehicleVisual(o.obj,v,dt);}}const before=room.phase==='countdown'&&roomClient.serverNow()<room.startAt;state=own.finishTime!==null||own.dnf?'results':before?'countdown':'racing';if(before){const seconds=Math.ceil((room.startAt-roomClient.serverNow())/1000);$('countdown').textContent=seconds>0?seconds:'HAYDİ!';$('countdown').hidden=false;}else $('countdown').hidden=true;elapsed=own.finishTime??room.elapsed;maxSpeed=own.topSpeed||0;$('timer').textContent=time(elapsed);$('speed').textContent=Math.round(velocity*3.6);$('remaining').textContent=Math.max(0,Math.ceil(track.length-progress))+' m';$('progressFill').style.width=clamp(progress/track.length*100,0,100)+'%';$('position').innerHTML=own.rank+' <span>/ '+room.players.length+'</span>';$('condition').textContent=Math.round(100-(own.v?.damage||0))+'%';$('driftBadge').hidden=!vehicle.isDrifting||state!=='racing';$('networkBadge').textContent=onlineConnection==='connected'?'◉ ODA '+room.code+' · '+Math.round(roomClient.rtt)+' ms':'◌ YENİDEN BAĞLANIYOR';$('standings').innerHTML=[...room.players].sort((a,b)=>a.rank-b.rank).map(p=>`<div class="${p.id===own.id?'is-player':''}"><b>${p.rank}</b><span>${escapeText(p.profile.name)}</span><small>${p.dnf?'BİTİREMEDİ':p.finishTime!==null?'FİNİŞ':p.id===own.id?'SEN':(p.v?.s>=progress?'+':'−')+Math.round(Math.abs((p.v?.s||0)-progress))+' m'}</small></div>`).join('');if(own.event&&own.event.id>onlineEventSeen){onlineEventSeen=own.event.id;if(own.event.kind==='water'||own.event.kind==='rock')sprayAt(own.event.kind);if($('sfxEnabled').checked){if(own.event.kind==='water')drivingAudio.splash(own.event.strength);else drivingAudio.hit(clamp(own.event.strength,0,.65));}}if(own.finishTime!==null||own.dnf)renderOnlineResults(room,own);const pose=chasePose(cart.position,vehicle.heading,cameraYaw,dt,camMode);cameraYaw=pose.yaw;camera.position.set(pose.position.x,pose.position.y,pose.position.z);camera.lookAt(pose.target.x,pose.target.y,pose.target.z);if(camera.fov!==pose.fov){camera.fov=pose.fov;camera.updateProjectionMatrix();}updateSun();if(precip?.visible){precip.position.copy(camera.position);const a=precip.geometry.attributes.position.array;for(let i=0;i<a.length;i+=3){a[i+1]-=dt*(track.weather==='snow'?3:32);a[i]+=dt;if(a[i+1]<-15)a[i+1]=55;if(a[i]>65)a[i]=-65;}precip.geometry.attributes.position.needsUpdate=true;}}
function renderOnlineResults(room,own){if(!onlineResultShown){onlineResultShown=true;$('resultStats').innerHTML=`<div>${own.rank}.<small>SIRALAMA</small></div><div>${own.dnf?'—':time(own.finishTime)}<small>SÜRE</small></div><div>${Math.round(own.topSpeed*3.6)}<small>EN YÜKSEK KM/SA</small></div>`;let ids=[];try{const read=JSON.parse(localStorage.getItem('artvin-online-rewards')||'[]');if(Array.isArray(read))ids=read;}catch{}let earned=0;if(!own.dnf&&!ids.includes(room.raceId)){earned=raceReward(own.rank,own.crashes,own.topSpeed*3.6);garageSave={...garageSave,credits:garageSave.credits+earned,races:garageSave.races+1};persistGarage();ids.push(room.raceId);try{localStorage.setItem('artvin-online-rewards',JSON.stringify(ids.slice(-50)));}catch{}}$('reward').textContent=own.dnf?'Yarış tamamlanamadı. Yeni odada tekrar deneyebilirsin.':earned?'+'+earned+' JETON · GARAJIN İÇİN KAZANDIN':'Yarış kaydın tamamlandı.';$('result').showModal();}const rows=[...room.players].sort((a,b)=>a.rank-b.rank),winner=rows.find(p=>p.finishTime!==null);$('resultsRows').innerHTML=rows.map(p=>`<tr class="${p.id===winner?.id?'winner ':''}${p.id===own.id?'you':''}"><td>${p.rank}</td><td><b>${escapeText(p.profile.name)}</b>${p.id===own.id?'<small>SEN</small>':''}</td><td>${escapeText(cars[p.profile.car].name)}</td><td>${p.dnf?'Bitiremedi':secondsText(p.finishTime)}</td><td>${p.finishTime===null||!winner?'—':p.id===winner.id?'LİDER':'+'+(p.finishTime-winner.finishTime).toFixed(2).replace('.',',')}</td></tr>`).join('');$('resultsStatus').textContent=room.phase==='finished'?'ORTAK YARIŞ SONUÇLARI':'ARKADAŞLARIN YARIŞI TAMAMLIYOR';const host=room.host===own.id;$('again').textContent=host?(room.phase==='finished'?'YENİ YARIŞ İÇİN ODAYA DÖN ↗':'ARKADAŞLARIN BEKLENİYOR…'):'DAVET ODASINA DÖN';$('again').disabled=host&&room.phase!=='finished';}
roomClient.addEventListener('race',e=>beginOnlineRace(e.detail));
roomClient.addEventListener('room',e=>{const room=e.detail;onlineRoom=room;renderRoom(room);if(room.phase==='lobby'){if(onlineActive){onlineActive=false;onlineResultShown=false;$('result').close();carIndex=Math.max(0,cars.findIndex(c=>c.id===garageSave.selected));build();menu();}$('onlineStatus').textContent='Bağlı · Odanız hazır';showRoomDialog();}else if(onlineActive)syncRoomHazards(room);});
roomClient.addEventListener('connection',e=>{onlineConnection=e.detail;if(e.detail==='reconnecting'){$('onlineStatus').textContent='Bağlantı kesildi, aynı odaya yeniden bağlanılıyor…';}else if(e.detail==='connected')$('onlineStatus').textContent='Sunucuya bağlanıldı.';});
roomClient.addEventListener('error',e=>{$('onlineStatus').textContent=e.detail;if(onlineActive&&state==='results')$('resultsStatus').textContent=e.detail;});
roomClient.addEventListener('left',restoreSolo);
$('onlineBtn').onclick=openOnline;$('onlineClose').onclick=()=>{if(roomClient.room)leaveOnline();else $('onlineDialog').close();};$('onlineDialog').addEventListener('cancel',e=>{e.preventDefault();if(roomClient.room)leaveOnline();else $('onlineDialog').close();});$('leaveRoom').onclick=leaveOnline;
async function roomAction(action){$('createRoom').disabled=$('joinRoom').disabled=true;$('onlineStatus').textContent='Odaya bağlanılıyor…';try{await action();}catch(err){$('onlineStatus').textContent=err.message;}finally{$('createRoom').disabled=$('joinRoom').disabled=false;}}
$('createRoom').onclick=()=>roomAction(()=>roomClient.create(onlineProfile(),trackIndex));$('joinRoomForm').addEventListener('submit',e=>{e.preventDefault();let code=$('joinCode').value.trim();try{code=new URL(code).searchParams.get('oda')||code;}catch{}code=code.toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code)){$('onlineStatus').textContent='6 karakterli oda kodunu veya tam davet bağlantısını yapıştır.';return;}roomAction(()=>roomClient.join(code,onlineProfile()));});$('readyRoom').onclick=()=>{const own=roomClient.room?.players.find(p=>p.id===roomClient.session?.id);if(own)roomClient.ready(!own.ready);};$('startRoom').onclick=()=>{if(roomClient.room?.phase==='finished')roomClient.rematch();else roomClient.start();};$('copyInvite').onclick=async()=>{try{await navigator.clipboard.writeText($('inviteLink').value);$('onlineStatus').textContent='Davet bağlantısı kopyalandı. Arkadaşına gönderebilirsin.';}catch{$('inviteLink').select();$('onlineStatus').textContent='Bağlantı seçildi. Ctrl+C ile kopyalayabilirsin.';}};
const invitedCode=new URL(location.href).searchParams.get('oda');if(roomClient.session){openOnline();roomAction(()=>roomClient.resume());}else if(invitedCode){openOnline();$('joinCode').value=invitedCode.toUpperCase();$('onlineStatus').textContent='Davetin hazır. Adını kontrol edip Odaya katıl düğmesine bas.';}
